import { useState, type FormEvent } from 'react';
import { JxButton, JxInputField, JxToastViewport, useJxToastQueue } from '@jinx-ui/react';

export default function SubscribeForm() {
  const toasts = useJxToastQueue();
  const [email, setEmail] = useState('');
  const [submitted, setSubmitted] = useState(false);

  const trimmed = email.trim();
  const invalid = !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed);
  const errorText = submitted && invalid ? 'Укажите адрес в формате name@example.com' : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setSubmitted(true);
    if (invalid) return;

    toasts.push({
      title: 'Готово',
      message: `Письмо отправлено на ${trimmed}`,
      variant: 'success',
    });
    setEmail('');
    setSubmitted(false);
  };

  return (
    <form
      onSubmit={submit}
      noValidate
      style={{ display: 'flex', flexDirection: 'column', gap: '16px', maxWidth: '360px' }}
    >
      <JxInputField
        label="Электронная почта"
        type="email"
        name="email"
        required
        autoComplete="email"
        placeholder="name@example.com"
        value={email}
        onChange={(event) => {
          setEmail(event.target.value);
          setSubmitted(false);
        }}
        errorText={errorText}
        helperText={errorText ? undefined : 'Пришлём письмо для подтверждения подписки'}
      />
      <JxButton type="submit" variant="primary" disabled={trimmed.length === 0}>
        Подписаться
      </JxButton>
      <JxToastViewport items={toasts.items} onDismiss={toasts.dismiss} position="top-right" />
    </form>
  );
}

